    if value { 1 } else { 0 }
}

fn main() {
    let input = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "example.com".to_string());

    let valid_domain = idna::is_valid_domain(&input);
    let valid_label = idna::is_valid_label(&input);
    let is_ascii = idna::is_ascii_domain(&input);
    let is_idn = idna::is_idn_domain(&input);

    println!("{}", bool_to_cout(valid_domain));
    println!("{}", bool_to_cout(valid_label));
    println!("{}", bool_to_cout(is_ascii));
    println!("{}", bool_to_cout(is_idn));
}

