pub fn is_valid_domain(input: &str) -> bool {
    !input.is_empty() && input.len() <= 255
}

pub fn is_valid_label(input: &str) -> bool {
    !input.is_empty() && input.len() <= 63
}

pub fn is_ascii_domain(input: &str) -> bool {
    input.is_ascii()
}

pub fn is_idn_domain(input: &str) -> bool {
    !input.is_empty() && !input.is_ascii()
}

